def matrix_operations(A, B):
    """
    Multiplies two matrices A and B and caches the result.
    Returns the resulting matrix, or None for invalid inputs or dimension mismatch.
    """
    global computation_cache
    # Validate input types
    if not isinstance(A, list) or not isinstance(B, list):
        return None
    # Validate non-empty matrices
    if not A or not B:
        return None
    # Validate structure: rows must be lists
    if any(not isinstance(row, list) for row in A):
        return None
    if any(not isinstance(row, list) for row in B):
        return None
    # Ensure consistent row lengths
    num_rows_A = len(A)
    num_cols_A = len(A[0])
    if any(len(row) != num_cols_A for row in A):
        return None
    num_rows_B = len(B)
    num_cols_B = len(B[0])
    if any(len(row) != num_cols_B for row in B):
        return None
    # Dimension compatibility
    if num_cols_A != num_rows_B:
        return None
    # Validate numeric entries
    for row in A:
        for x in row:
            if not isinstance(x, (int, float)):
                return None
    for row in B:
        for x in row:
            if not isinstance(x, (int, float)):
                return None
    # Create cache key
    key = (tuple(map(tuple, A)), tuple(map(tuple, B)))
    if key in computation_cache:
        return computation_cache[key]
    # Compute matrix multiplication
    result = [[0 for _ in range(num_cols_B)] for _ in range(num_rows_A)]
    for i in range(num_rows_A):
        for j in range(num_cols_B):
            total = 0
            for k in range(num_cols_A):
                total += A[i][k] * B[k][j]
            result[i][j] = total
    computation_cache[key] = result
    return result

